"use client"

import { ChartLines, type LineChartProps } from "@/components/ui/line-chart"

type AreaChartProps = LineChartProps

/**
 * Volume as a barcode: no fill, only hairlines dropped from the line to the baseline at a close,
 * even rhythm. Several series stack, each band its own rhythm, and the readout sums them.
 */
function AreaChart(props: AreaChartProps) {
  return <ChartLines {...props} area />
}

export { AreaChart, type AreaChartProps }

@layer components {
  /* ── ot-area-chart ── volume as a barcode: no fill, only hairlines dropped from the line to the
     baseline at a close even rhythm, SPECTRA's barcode laid under a line. Stacked series each keep
     their own rhythm, three, six and twelve pixels apart, so the bands read by density, not colour. */
  .ot-area-chart-drops { stroke: none; }
  .ot-area-chart .ot-line-chart-draw pattern > rect { fill: var(--ot-rule-strong); }
  .ot-area-chart .ot-line-chart-draw > [data-series="0"] pattern > rect { fill: var(--ot-pencil); }
  .ot-area-chart.ot-chart .ot-line-chart-draw > [data-series] > .ot-line-chart-line { stroke: var(--ot-ink); stroke-dasharray: none; }
  .ot-area-chart.ot-chart .ot-chart-swatch { --c: var(--ot-pencil); block-size: 0.8em; background: repeating-linear-gradient(to right, var(--c) 0 1px, transparent 1px 3px); }
  .ot-area-chart.ot-chart .ot-chart-row[data-series="1"] .ot-chart-swatch { background: repeating-linear-gradient(to right, var(--c) 0 1px, transparent 1px 6px); }
  .ot-area-chart.ot-chart .ot-chart-row[data-series="2"] .ot-chart-swatch { background: repeating-linear-gradient(to right, var(--c) 0 1px, transparent 1px 12px); }

  @media (forced-colors: active) {
    .ot-area-chart .ot-line-chart-draw pattern > rect { fill: GrayText; }
  }
}
